INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-073', 'EG', 'P3', 'OPEN', 'research', 'add-source: journal_name and publisher', 'WRITER GAP (rule 10: filed, not patched). add-source has no flag for journal_name or publisher and correct-source cannot set them, so the four literature admissions of this batch (REF-01033 to REF-01036) are stamped metadata_quality COMPLETE while journal_name (and, for three, publisher) are NULL although their persisted Crossref payloads supply them; retrieval_log.py --verify-authors reports it. The same shape holds on earlier admissions (REF-00983 and others). The tooling fix is its own PR; the stamp cannot be lowered through amend-source either (metadata_quality is not an amendable judgement field).', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL, NULL);
