INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-00139-MOB', 'REF-00139', 'MOB', 'no participants; a regulatory text (Singapore Code on Accessibility 2025, v1.1)', NULL, 'PROXY', 'PROXY by construction: a code asserts a figure; it does not study a population. Same grading as the other codes of the slug (REF-01031, REF-01032).', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-00139', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01033-MOB', 'REF-01033', 'MOB', 'sixteen unimpaired people (non-wheelchair users) propelling a wheelchair 120 m at 8%', 16, 'PROXY', 'General-population participants: the distance-effect result (effort and heart rate rising with distance) is a proxy for wheelchair users, not their measurement. It is the only held source that measures effort against distance on a slope.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01033', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01033-SCI', 'REF-01033', 'SCI', 'five wheelchair users with cervical cord injury, 3 m laboratory slope at 5 to 12.5%', 5, 'PARTIAL', 'Matches the group. The abstract reports mean normalized power at 5%, 6.7% and 8.3% (not at 10% or 12.5%) and a significant between-person difference in the ability to climb a slope; n=5 and no threshold is set, so the result shows the spread of ability, not a safe gradient.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01033', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01034-MOB', 'REF-01034', 'MOB', '27 adults: manual wheelchair users, power wheelchair users, and people with vision impairment using a cane or service animal; transit-bus boarding ramps', 27, 'PARTIAL', 'Wheelchair users are in the sample; the abstract says it was small and excluded scooter and ambulation-aid users, and the ramps are vehicle ramps, so slopes steeper than a building ramp are in question. ''Most participants'' pools wheelchair users with people with vision impairment.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01034', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01035-MS', 'REF-01035', 'MS', '18 ambulatory people with multiple sclerosis (mean EDSS 2.9) and 23 healthy adults, treadmill', 18, 'PARTIAL', 'People with MS, but ambulatory and mildly affected (EDSS 2.9); those who use a wheelchair or other aid on ramps are not in the sample. Treadmill, not a built ramp.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01035', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01036-MOB', 'REF-01036', 'MOB', '26 ''qualified'' older adults, each walking up and down an incline with a cane and with a rolling walker as experimental conditions', 26, 'PROXY', 'The abstract states no impairment, no balance deficit and no habitual use of either device, and no wheelchair users are in the sample; the participants are older adults handed each device in a gait laboratory. Graded PROXY for people with mobility needs. Incline angle not stated.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01036', NULL);
