INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (119, 'REF-00139', NULL, 3, 'MOB', NULL, NULL, NULL, 'SG', 'ramp', 'numerical', '1:12', 'rise:run ratio', 'Changes in vertical rise (mm) Gradient not steeper than 0 to 15 1:2 More than 15 to 50 1:5 More than 50 to 175 1:10 Exceeding 175 1:12', 'Code on Accessibility 2025, 4.5.1, Table 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.5', '4.5.1', NULL, 'Table 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Quantity: maximum gradient where the change in vertical rise exceeds 175 mm. Current edition (v1.1). Table 4 steps the permitted gradient by rise: 1:2 to 15 mm, 1:5 to 50 mm, 1:10 to 175 mm, 1:12 above. 4.6.2.1 requires a ramp to meet Table 4 and be consistent between landings. Read from the page image (PDF page 43).', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
