INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (155, 'REF-00139', NULL, 8, 'MOB', NULL, NULL, NULL, 'SG', 'ramp', 'absent', NULL, NULL, 'The colour of the door must contrast with the door frame or the wall.', 'Code on Accessibility in the Built Environment 2025, 4.4.1.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.4', '4.4.1', '4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'The Code requires door-to-frame colour contrast but states no Light Reflectance Value or luminance difference; the passage that would carry a figure carries none.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
