INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (158, 'REF-01033', NULL, 3, 'SCI', NULL, NULL, NULL, NULL, 'laboratory slope, 3 m', 'range', '5 to 12.5', '%', 'five wheelchair users with cervical cord injury were examined to evaluate the influence of different gradients (5%, 6.7%, 8.3%, 10% and 12.5%) with 3m length in laboratory', 'Abstract (Crossref and PubMed records)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Quantity: gradients tested, 3 m long, five wheelchair users with cervical cord injury. The tested gradients are the condition under which the two findings below hold. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'condition', 'between');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (159, 'REF-01033', NULL, 3, 'SCI', NULL, NULL, NULL, NULL, 'laboratory slope, 3 m', 'qualitative', 'significant difference between each subject in the ability to climb a slope', NULL, 'the normalized power of subjects with cervical cord injury was significant difference between each subject in the ability to climb a slope', 'Abstract (Crossref and PubMed records)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'The between-person spread, not the mean, is what bears on a design value; the abstract sets no threshold. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (160, 'REF-01033', NULL, 3, 'SCI', NULL, NULL, NULL, NULL, 'laboratory slope, 3 m', 'qualitative', 'Mean normalized power were 0.23W/kg on a 5% slope, 0.24W/kg on 6.7%, and 0.26W/kg on 8.3%', NULL, 'Mean normalized power were 0.23W/kg on a 5% slope, 0.24W/kg on 6.7%, and 0.26W/kg on 8.3% respectively.', 'Abstract (Crossref and PubMed records)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Five people, so the means rest on n=5; no figure is given for 10% or 12.5%. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (161, 'REF-01034', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'transit bus boarding ramp (vehicle, not a building)', 'qualitative', 'usable and acceptable for most participants', NULL, 'The 1:8 and 1:12 slopes were usable and acceptable for most participants.', 'Abstract (landing page)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Lens MOB is the wheelchair users among the participants; the sample also included people with vision impairment. 27 adults: manual wheelchair users, power wheelchair users, and people with vision impairment using a cane or service animal; four slopes, the abstract names 1:4, 1:8 and 1:12 only. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (162, 'REF-01034', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'transit bus boarding ramp (vehicle, not a building)', 'qualitative', 'too steep for safe unassisted boarding and disembarking', NULL, 'The data indicate that the 1:4 slope is too steep for safe unassisted boarding and disembarking.', 'Abstract (landing page)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Lens MOB is the wheelchair users among the participants; the sample also included people with vision impairment. A vehicle boarding ramp, so a steeper slope than a building ramp is in question. A failure finding. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (163, 'REF-01034', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'transit bus boarding ramp (vehicle, not a building)', 'qualitative', 'lacked the strength needed for unassisted ascent', NULL, 'Many manual wheelchair users lacked the strength needed for unassisted ascent.', 'Abstract (landing page)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Which slopes are meant is not stated in the abstract. An inadequacy finding. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (164, 'REF-01035', NULL, 3, 'MS', NULL, NULL, NULL, NULL, 'treadmill, level, uphill and downhill walking', 'qualitative', 'most demanding effort was during uphill walking', NULL, 'The most demanding effort was during uphill walking, with pwMS rating it more demanding compared with the healthy controls.', 'Abstract (PubMed record 36458477)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Eighteen ambulatory people with multiple sclerosis (mean EDSS 2.9) and 23 healthy adults; slope not stated in the abstract. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (165, 'REF-01035', NULL, 3, 'MS', NULL, 'A-EFFORT', NULL, NULL, 'treadmill, level, uphill and downhill walking', 'qualitative', 'describe the effort of walking on different slopes higher than normal', NULL, 'pwMS describe the effort of walking on different slopes higher than normal, regardless of the energy expenditure values.', 'Abstract (PubMed record 36458477)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (166, 'REF-01036', NULL, 3, NULL, 'd450', NULL, NULL, NULL, 'incline walking, rolling walker (RW) and cane', 'qualitative', 'no differences were seen with cane use', NULL, 'With the RW use, downward walking show a faster velocity, higher cadence, less stance time, bigger steps and strides than upward walking (p≤.05); but no differences were seen with cane use.', 'Abstract (PubMed record 37540908)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Twenty-six "qualified" older adults each walked with a cane and a rolling walker as experimental conditions; the abstract states no impairment and no habitual device use, so no identity lens is attached (the functional lens d450, walking, is). Incline angle not stated. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing. [VERBATIM-EXEMPT: the persisted PubMed XML spells the less-than-or-equal sign as the character reference &#x2264; (p&#x2264;.05); the quote is the decoded text and the only mismatch is that spelling]', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (167, 'REF-01033', NULL, 12, NULL, NULL, 'A-EFFORT', NULL, NULL, 'long sidewalk slope, 120 m at 8%', 'qualitative', 'the extremely high exercise intensity at a final interval', NULL, 'A mean oxygen uptake and heart rate were increased as the distance increased and their results indicated the extremely high exercise intensity at a final interval that were 1.2liter /min and 152bpm.', 'Abstract (Crossref and PubMed records)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'PROXY: sixteen unimpaired subjects (non-wheelchair users) propelling a wheelchair on a 120 m, 8% slope (the abstract frames it as a sidewalk); no figure for wheelchair users on the long slope. It is the only held source measuring effort against distance on a slope, which is the quantity a rest landing interrupts. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (82, 91, 'NAMES-EXISTING', 'TERM-091', 'Singapore Code on Accessibility 2025, clause 4.6.5.2(b): landings are ''provided at regular intervals based on the gradient provided and the run of the ramp must not be more than what is shown in Table 5'', whose column is headed ''Maximum run of ramp (mm)''. The run is the length between landings, which is TERM-091''s definition (the horizontal length of a single ramp flight between landings). [ASSUMPTION: ''run'' here means the horizontal length, as the table''s values (6000 to 18000 mm at 1:12 to 1:24) and Figure 32 (''Max run in accordance with Table 5'', drawn between landings) show; the clause does not say ''horizontal''.] Warrant: the persisted PDF, page 47, rendered and read.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (83, 93, 'NAMES-EXISTING', 'TERM-089', 'Lenker et al. 2016 abstract: ''access ramps used in transit vehicles'', tested at four slopes. A transit-bus boarding ramp is a built inclined surface that bridges a level difference on a route, which is TERM-089''s definition. [ASSUMPTION: TERM-089''s scope is read to include a vehicle boarding ramp; its definition excludes the running slope of paths and does not mention vehicles, and the owner''s ledger marks the reading of ''ramp'' terms as unratified.] Warrant: the abstract on the persisted landing page; no full text was read.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (84, 92, 'DEFERRED', NULL, 'Hashizume et al. 2015 abstract: ''a long slope with 120m distance and 8% gradient'' on a sidewalk, with wheelchair users propelling it. It is a continuous slope of 120 m with no landing, so it is neither TERM-091 (a flight between landings) nor TERM-001 on its face; whether it names an existing term, a new one (continuous slope length) or none is the owner''s to rule. Left unadjudicated by this session.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (85, 94, 'DEFERRED', NULL, 'Har-Nir et al. 2023 abstract: ''level, uphill and downhill slopes'' of a treadmill, walked by people with multiple sclerosis. A treadmill slope is an experimental condition, not a built ramp (TERM-089) and not stated as a design gradient (TERM-001); whether the phrase names any term is the owner''s to rule. Left unadjudicated by this session.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (86, 95, 'DEFERRED', NULL, 'Liu et al. 2023 abstract and title: walking ''up and down an incline'' with a cane and a rolling walker; the angle is not given. An incline walked in a gait laboratory is an experimental condition, not a built ramp (TERM-089) and not a stated design gradient (TERM-001); whether the phrase names any term is the owner''s to rule. Left unadjudicated by this session.', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-31 05:26', 'session_2026-10-30-ramp-spec-pages-rebuild');
